insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('margaretn', 'Margaretn', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Margareten', '[{"kategorie": "wörtlich", "text": "\"Wien-Margareten\""}, {"kategorie": "", "text": "\"der fünfte [[Hieb]]\" (= 5. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Margareten gehört zu den inneren Stadtbezirken Wiens und ist ein urbanes, dicht besiedeltes Gebiet, das für seine Mischung aus traditioneller Wiener Architektur, multikulturellem Flair und einem reichen kulturellen Leben bekannt ist"}, {"kategorie": "", "text": "Margareten war bis 1850 ein eigenständiges Dorf in der Wiener Vorstadt. Mit der Eingemeindung nach Wien im Jahr 1850 wurde es Teil des 4. Bezirks. 1861 wurde Margareten dann zum eigenständigen 5. Bezirk. Margareten erhielt seinen Namen vermutlich von einer Kirche, die der Heiligen Margareta von Antochia geweiht war"}, {"kategorie": "", "text": "Heute ist Margareten ein urbaner, dicht bebauter Bezirk, der durch seine Mischung aus [[Altbauvierteln]], [[Gemeindebauten]], moderner Architektur und kreativer Szene auffällt. Er ist bekannt für seine typischen [[Wiener]] Zinshäuser ([[Gründerzeitarchitektur]]), viele [[Gemeindebauten]] (darunter einige der ersten der Stadt) und eine multikulturelle Bevölkerung mit lebendiger Gastronomie- und Kulturszene"}, {"kategorie": "", "text": "Die bekanntesten [[Grätzln]] Margaretens sind der [[Margaretenplatz]] (mit dem [[Schlossquadrat]] – Szeneviertel mit Lokalen, Bars, urbanem Flair), die [[Reinprechtsdorfer]] Straße (wichtige Verkehrs- und Geschäftsstraße), die [[Pilgramgasse]] (Übergang in den 6. Bezirk), die [[Schönbrunner]] Straße (wichtige Ost-West-Achse) und der [[Matzleinsdorfer]] Platz (Verkehrsknotenpunkt am südlichen Rand)"}, {"kategorie": "", "text": "Margareten ist ein urbaner, kompakter, vielfältiger und sehr zentral gelegener Wiener Bezirk. Er verbindet traditionelle Wiener Bauweise mit modernen Entwicklungen und einer jungen, kreativen Szene. Durch seine Lage innerhalb des Gürtels ist er besonders beliebt bei Studierenden, Künstler:innen und jungen Berufstätigen"}]'::jsonb, ''),
  ('ziaglmuseum', 'Ziaglmuseum', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Ziegelmuseum', '[{"kategorie": "allg.", "text": "\"kleines Spezialmuseum in [[Wien-Margareten]], das sich der Geschichte der Ziegelproduktion in Wien und insbesondere dem sogenannten \"Wienerberger Ziegelofen\" widmet. Es zeigt die historische Bedeutung der Ziegelarbeiter ([[Ziaglbeem]]), die insbesondere im 19. Jahrhundert eine zentrale Rolle beim Bau der Stadt Wien spielten"}, {"kategorie": "", "text": "Ab dem 18. und vor allem 19. Jahrhundert wurden große Teile Wiens mit Ziegeln gebaut, die in den Ziegeleien am Stadtrand – vor allem in [[Wien-Favoriten]] (ehemals Ziegelfeld) – produziert wurden. Die Arbeiter, meist aus Böhmen und Mähren, lebten unter oft extrem einfachen Bedingungen – das Leben der [[Ziaglbeem]] ist heute Teil der Wiener Arbeiter- und Migrationsgeschichte. Das Museum dokumentiert diese Ära der industriellen Stadtentwicklung, der sozialen Kämpfe und des Alltagslebens der Arbeiterklasse"}, {"kategorie": "", "text": "Das Ziegelmuseum Margareten ist ein kleines, aber bedeutendes Bezirksmuseum, das einen oft vergessenen Teil der Wiener Stadtentwicklung und Sozialgeschichte dokumentiert. Es erinnert an die Lebensrealität der Ziegelarbeiter, die mit ihrer harten Arbeit die Grundlage für das moderne Wien gelegt haben. In Zeiten von Industrialisierung, Migration und Urbanisierung ist es ein Mahnmal der Geschichte und ein Ort des Erinnerns und Verstehens."}]'::jsonb, ''),
  ('fueuemcasino', 'Füümcasino', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Filmcasino', '[{"kategorie": "wörtlich", "text": "traditionsreiches Programmkino im 5. Wiener Gemeindebezirk ([[Margareten]])"}, {"kategorie": "", "text": "Es ist bekannt für sein künstlerisch anspruchsvolles Filmprogramm, seine stilvolle 1950er-Jahre-Atmosphäre und seine Rolle als wichtige Spielstätte für Filmfestivals und cineastische Sonderveranstaltungen"}, {"kategorie": "", "text": "Eröffnet wurde das Filmcasino im Jahr 1954, ursprünglich als klassisches Lichtspieltheater der 50er-Jahre. Im Laufe der Jahrzehnte wandelte es sich vom typischen Stadtteilkino zum Art-House-Kino mit kulturpolitischem Anspruch. In den 1980ern und 1990ern drohte die Schließung – es wurde aber renoviert und gerettet, unter anderem durch engagierte Cineasten. Heute gilt es als eines der schönsten Kinos Wiens mit originaler 50er-Jahre-Innenausstattung und einem besonders charmanten Flair"}, {"kategorie": "", "text": "Das Filmcasino ist ein kulturelles Juwel im Wiener Bezirksleben, das Filmgeschichte, künstlerischen Anspruch und politische Bildung auf einzigartige Weise verbindet. Es bietet nicht nur Kino, sondern auch Raum für Diskurs, Vielfalt und kreative Entfaltung. Für [[Margareten]] ist es ein kultureller Leuchtturm mit hoher lokaler und internationaler Bedeutung."}]'::jsonb, ''),
  ('margaretnhof', 'Margaretnhof', '', '', '', 'Wiener Gemeindebauten', 'Margaretenhof', '[{"kategorie": "allg.", "text": "historisches Wohngebäude im 5. Wiener Gemeindebezirk ([[Margareten]]), das als großflächiger Wohnblock zwischen der Margaretenstraße, der Schönbrunner Straße und der Spengergasse liegt"}, {"kategorie": "", "text": "Der Margaretenhof zählt zu den bedeutendsten Bauten der [[Gründerzeit]] in Wien und ist ein beeindruckendes Beispiel für den Wohnbau dieser Epoche"}, {"kategorie": "", "text": "Er wurde zwischen 1884 und 1885 erbaut und zeichnet sich durch seine reich dekorierte Fassade im Stil des [[Historismus]] aus, der Elemente der Neorenaissance und des Neobarocks miteinander verbindet"}, {"kategorie": "", "text": "Besonders auffällig sind die kunstvollen Ornamente, die Erker und Balkone sowie die aufwändig gestalteten Fassadendetails, die dem Gebäude einen repräsentativen Charakter verleihen."}]'::jsonb, ''),
  ('mariahueuef', 'Mariahüüf', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Mariahilf', '[{"kategorie": "wörtlich", "text": "\"Wien-Mariahilf\""}, {"kategorie": "", "text": "\"der sechste [[Hieb]]\" (= 6. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Mariahilf gehört zu den inneren Stadtbezirken Wiens und grenzt im Norden an den 7. Bezirk ([[Neubau]]), im Osten an den 1. Bezirk ([[Innere]] Stadt) und den 4. Bezirk ([[Wieden]]), im Süden an den 5. Bezirk ([[Margareten]]) und im Westen an den 15. Bezirk ([[Rudolfsheim-Fünfhaus]]). Er erstreckt sich von der [[Mariahilfer]] Straße, einer der wichtigsten Einkaufsstraßen Wiens, bis zum [[Gürtel]], der den inneren und äußeren Stadtbereich trennt"}, {"kategorie": "", "text": "Der Bezirk wurde ursprünglich aus Vorstädten wie [[Laimgrube]], [[Gumpendorf]] und [[Windmühle]] gebildet. 1850 wurde Mariahilf als eigenständiger Bezirk gegründet, der Name stammt von der [[Mariahilfer]] Kirche (Wallfahrtskirche). Ab dem 19. Jahrhundert entwickelte sich Mariahilf zu einem bürgerlich-kreativen Stadtteil und spielte eine wichtige Rolle in der Entwicklung des [[Roten]] Wien"}, {"kategorie": "", "text": "Zu den wichtigsten Sehenswürdigkeiten zählen die [[Mariahilfer]] Straße (eine der bekanntesten Einkaufsstraßen Österreichs), der [[Naschmarkt]] (beliebter Markt mit Restaurants), der [[Esterházypark]] und das [[Haus]] des Meeres (Tropenhaus & Aquarium im ehemaligen [[Flakturm]]), die [[Wienzeile]] (Architektur von Otto Wagner sichtbar), sowie das [[Theater]] an der Wien (traditionsreiches Theater an der Linken Wienzeile), das [[Raimundtheater]] (bekanntes Musiktheater der [[Vereinigten]] Bühnen Wien), das [[Theater]] an der Gumpendorfer Straße (TAG – innovatives Off-Theater), das [[Philharmonikerhaus]] (Geburtshaus von Franz Lehár), sowie kleine Galerien & Off-Spaces in den Seitenstraßen"}, {"kategorie": "", "text": "Mariahilf ist ein kompakter, kreativer und kulturell lebendiger Stadtteil mit hoher Lebensqualität und direkter Nähe zur Innenstadt. Durch seine Einkaufsstraße, die Kunst- und Kulturszene, sowie seine soziale Offenheit gehört Mariahilf zu den beliebtesten innerstädtischen Bezirken Wiens."}]'::jsonb, ''),
  ('raimundteata', 'Raimundteata', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Raimundtheater', '[{"kategorie": "allg.", "text": "eines der bedeutendsten Theater Wiens, das zu den wichtigsten Musicalbühnen im deutschsprachigen Raum zählt und sich im 6. Wiener Gemeindebezirk ([[Mariahilf]]) befindet. Es ist Teil der [[Vereinigten]] Bühnen Wien (VBW) und bekannt für hochwertige Musicalproduktionen (sowohl internationale als auch österreichische Uraufführungen)"}, {"kategorie": "", "text": "Das Raimundtheater wurde am 28. November 1893 eröffnet und ist nach dem berühmten österreichischen Dramatiker Ferdinand Raimund benannt. Ursprünglich ein Volkstheater mit Fokus auf Wiener Volksstücke und klassische Dramen, wurde es ab Mitte des 20. Jahrhunderts zunehmend für Operetten und Musicals genutzt (seit den 1980er-Jahren verstärkter Fokus auf Musicalproduktionen)"}, {"kategorie": "", "text": "Das Raimundtheater vereint Wiener Theatertradition mit internationaler Musical-Exzellenz. Es steht für opulente Produktionen, starke Emotionen, musikalische Perfektion und ein Publikumserlebnis auf höchstem Niveau. Mit seiner Historie, seinem künstlerischen Anspruch und seiner modernen Ausstattung zählt es zu den wichtigsten Kulturinstitutionen Wiens."}]'::jsonb, ''),
  ('filharmonikahaus', 'Filharmonikahaus', '', '', '', 'Wiener Gemeindebauten', 'Philharmonikerhaus', '[{"kategorie": "allg.", "text": "historisches Wohn- und Kulturgebäude in Wien, das insbesondere durch seine enge Verbindung zu den Wiener Philharmonikern und namhaften Musikern der österreichischen Klassikgeschichte bekannt wurde. Es befindet sich im 6. Wiener Gemeindebezirk ([[Mariahilf]]) und hat musikgeschichtliche Bedeutung als Wohnort berühmter Komponisten und Musiker (Geburtshaus von Franz Lehár)"}, {"kategorie": "", "text": "Erbaut in der zweiten Hälfte des 19. Jahrhunderts, war es ursprünglich konzipiert als bürgerliches Wohnhaus für Musiker, darunter Mitglieder der Wiener Philharmoniker. Das Gebäude ist ein Teil der Wiener Musiktradition, da es über Jahre hinweg von Mitgliedern der [[Wiener]] Philharmoniker, Orchestermusikern und teilweise auch von Komponisten bewohnt wurde. Es wurde daher auch als \"Philharmonikerhaus\" bezeichnet, obwohl es keine Konzertstätte, sondern ein Wohngebäude ist (nicht zu verwechseln mit dem [[Wiener]] Musikverein, der ebenfalls eng mit den [[Wiener]] Philharmonikern verbunden ist und oft als „Heimstätte“ der Philharmoniker gilt)."}]'::jsonb, ''),
  ('voiksteata', 'Voiksteata', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Volkstheater', '[{"kategorie": "allg.", "text": "\"eines der größten und bedeutendsten Sprechtheater im deutschsprachigen Raum\""}, {"kategorie": "", "text": "Es befindet sich im 7. Wiener Gemeindebezirk ([[Neubau]]) und hat eine lange Tradition als Bühne für klassische und moderne Theaterproduktionen"}, {"kategorie": "", "text": "Das Volkstheater wurde 1889 auf Initiative des liberalen Wiener Bürgertums gegründet. Ziel war es, ein Theater zu schaffen, das auch einem breiten Publikum zugänglich ist, im Gegensatz zu den eher aristokratisch orientierten Häusern wie dem [[Burgtheater]]"}, {"kategorie": "", "text": "Die Architektur des Volkstheaters ist geprägt von einer imposanten Fassade mit einem [[Portikus]], der von Säulen getragen wird, sowie von reichen Dekorationen im Inneren. Der Zuschauerraum ist klassisch gestaltet und bietet Platz für etwa 1.200 Zuschauer"}, {"kategorie": "", "text": "Das Repertoire des Volkstheaters umfasst ein breites Spektrum von klassischen Dramen über moderne Theaterstücke bis hin zu experimentellen Inszenierungen. Das Theater legt großen Wert darauf, sowohl die großen Werke der Weltliteratur als auch zeitgenössische Stücke aufzuführen."}]'::jsonb, ''),
  ('neibau', 'Neibau', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Neubau', '[{"kategorie": "wörtlich", "text": "\"Wien-Neubau\""}, {"kategorie": "", "text": "\"der siebente [[Hieb]]\" (= 7. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Neubau gehört zu den inneren Bezirken Wiens und grenzt im Osten an den 1. Bezirk ([[Innere]] Stadt), im Süden an den 6. Bezirk ([[Mariahilf]]), im Westen an den 15. Bezirk ([[Rudolfsheim-Fünfhaus]]) und im Norden an den 8. Bezirk ([[Josefstadt]]) sowie den 9. Bezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Der Name \"Neubau\" stammt aus dem 16. Jahrhundert und geht auf eine neue Ansiedlung zurück, die damals außerhalb der Wiener Stadtmauern entstand. Der Bezirk entwickelte sich rasch zu einem urbanen Gebiet und wurde im 19. Jahrhundert ein Teil von Wien"}, {"kategorie": "", "text": "Neubau hat eine lange Geschichte als Arbeiter- und Handwerkerviertel, das im Laufe der Zeit eine starke industrielle Prägung erfuhr. Viele der heute erhaltenen Gebäude stammen aus der [[Gründerzeit]] des 19. Jahrhunderts"}, {"kategorie": "", "text": "Entstanden aus mehreren Vorstädten, u. a. [[Spittelberg]], [[Schottenfeld]], [[Neubau]], wurde \"Neubau\" 1850 zum eigenen Bezirk erklärt. Heute ist Neubau ist ein Zentrum der Kreativszene in Wien und bekannt für seine vielen kleinen Galerien, Ateliers, Designerläden und unabhängigen Boutiquen"}, {"kategorie": "", "text": "Zu den Wichtige Grätzln und Sehenswürdigkeiten zählen die [[Mariahilfer]] Straße (Hauptgeschäftsstraße, teils Fußgängerzone), der [[Spittelberg]] (historisches Biedermeier-Viertel mit engen Gassen, Lokalen und Kunsthandwerk), die [[Siebensterngasse]] (alternative Einkaufsmeile mit Cafés und Boutiquen), die [[Neubaugasse]] (stylische Einkaufsstraße mit unabhängigen Geschäften), das [[MuseumsQuartier]] (MQ - einer der größten Kulturkomplexe Europas), das [[Leopold]] Museum (Egon Schiele, Wiener Moderne), das [[mumok]] (Museum moderner Kunst), die [[Kunsthalle]] Wien (Ausstellungshaus der Stadt Wien für internationale zeitgenössische Kunst), das [[Architekturzentrum]] Wien (Sitz von Kulturinitiativen wie [[Tanzquartier]], [[Zoom]] Kindermuseum Innenhöfe und Lokale als Treffpunkt der Kulturszene), der [[Spittelberger]] Weihnachtsmarkt (einer der charmantesten Weihnachtsmärkte Wiens – mit Fokus auf Kunsthandwerk und Kulinarik), sowie das [[Volkstheater]] (an der Grenze zum 1. Bezirk) und zahlreiche Galerien, Off-Spaces, Pop-up-Stores, Street-Art-Flächen"}, {"kategorie": "", "text": "Neubau ist das kreative, hippe und kulturell aufgeladene Herz Wiens. Der Bezirk verbindet historische Architektur mit zeitgenössischer Kunst und Kultur, progressivem Denken und einer lebendigen urbanen Szene. Ob Kunst, Design, Theater oder einfach guter Kaffee – Neubau ist Wiens pulsierendes Trendviertel mit internationalem Flair."}]'::jsonb, ''),
  ('josefschdodt', 'Josefschdodt', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Josefstadt', '[{"kategorie": "wörtlich", "text": "\"Wien-Josefstadt\""}, {"kategorie": "", "text": "\"der achte [[Hieb]]\" (= 8. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Josefstadt gehört zu den inneren Bezirken Wiens und ist einer der kleinsten Bezirke Wiens, sowohl in Bezug auf die Fläche als auch die Einwohnerzahl"}, {"kategorie": "", "text": "Er liegt westlich der [[Inneren]] Stadt und ist für sein historisches Ambiente, seine bürgerliche Prägung und seine zentrale Lage bekannt. Josefstadt hat den Ruf eines gehobenen Wohnbezirks, der eine hohe Lebensqualität bietet und zugleich eine reiche kulturelle und historische Tradition pflegt"}, {"kategorie": "", "text": "Der Name \"Josefstadt\" geht auf [[Kaiser]] Joseph I. zurück, unter dessen Herrschaft der Bezirk im frühen 18. Jahrhundert als bürgerliche Vorstadt angelegt wurde. Die Gegend entwickelte sich rasch zu einem beliebten Wohnort für das wohlhabende Bürgertum. Der Bezirk entstand im 18. Jahrhundert durch die Zusammenlegung mehrerer Vorstädte, darunter [[Josefstadt]], [[Breitenfeld]], [[Strozzigrund]] und [[Altlerchenfeld]], und ist seit 1850 ein eigenständiger Bezirk. Schon früh war die Josefstadt Sitz von Hochschulen, Adelspalais und Kulturbetrieben und ist auch heute ein gehobener, akademisch geprägter Bezirk"}, {"kategorie": "", "text": "Wichtige Einrichtungen und Gebäude sind das [[Theater]] in der Josefstadt (ältestes noch bespieltes Theater Wiens, gegründet 1788), die [[Universität]] Wien (1365 gegründet und somit die älteste Universität im heutigen deutschen Sprachraum), das [[Alte]] AKH (Campus der Universität Wien), das [[Palais]] Strozzi und das [[Volkskundemuseum]] im [[Palais]] Schönborn"}, {"kategorie": "", "text": "Die Josefstadt ist geprägt von eleganten Bauten aus der [[Biedermeierzeit]] und der [[Gründerzeit]]. Die Straßen und Plätze in Josefstadt, wie die [[Josefstädter]] Straße und der [[Piaristenplatz]], sind von charmanten historischen Gebäuden gesäumt, die dem Bezirk ein malerisches und einladendes Flair verleihen"}]'::jsonb, ''),
  ('hamerlingpark', 'Hamerlingpark', '', '', '', 'Wiener Parks und Parkanlagen', 'Hamerlingpark', '[{"kategorie": "allg.", "text": "kleine, aber charmante Grünfläche im 8. Wiener Gemeindebezirk ([[Josefstadt]]), in der Nähe der [[Josefstädter]] Straße, zwischen der Skodagasse und der Stolzenthalergasse"}, {"kategorie": "", "text": "Der Park wurde nach Robert Hamerling (1830–1889), einem bedeutenden österreichischen Dichter und Schriftsteller, benannt. Er war einer der prominentesten Vertreter der deutschsprachigen Dichtung im 19. Jahrhundert"}, {"kategorie": "", "text": "Der Hamerlingpark ist Teil eines größeren Areals, das früher als Hamerlingplatz bekannt war. In diesem Bereich gab es ursprünglich eine Kaserne, die in den 1970er Jahren abgerissen wurde, um Platz für Wohnbauten und den Park zu schaffen"}, {"kategorie": "", "text": "Heute ist der Park ist eine ruhige Grünfläche mit Rasenflächen, Bäumen und Bänken, die zum Entspannen und Verweilen einladen."}]'::jsonb, ''),
  ('oisagrund', 'Oisagrund', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Alsergrund', '[{"kategorie": "wörtlich", "text": "\"Wien-Alsergrund\""}, {"kategorie": "", "text": "\"der neunte [[Hieb]]\" (= 9. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Alsergrund gehört zu den inneren Bezirken Wiens und liegt nördlich der [[Inneren]] Stadt"}, {"kategorie": "", "text": "Der Bezirk entstand 1850 durch die Eingemeindung mehrerer Vororte, darunter [[Alsergrund]], [[Lichtental]], [[Rossau]], [[Währing]] (teilweise), [[Michelbeuern]], [[Thurygrund]], [[Althangrund]]. Der Name „Alsergrund“ leitet sich vom Alsbach ab, einem kleinen Fluss, der früher durch das Gebiet floss, heute jedoch größtenteils unterirdisch verläuft"}, {"kategorie": "", "text": "Alsergrund ist bekannt für seine vielen Krankenhäuser und medizinischen Einrichtungen. Das [[Allgemeine]] Krankenhaus der Stadt Wien ([[AKH]]), eines der größten Krankenhäuser Europas, befindet sich im Bezirk und ist ein bedeutendes Zentrum für medizinische Versorgung und Forschung"}, {"kategorie": "", "text": "Alsergrund ist reich an kulturellen Einrichtungen und Sehenswürdigkeiten. Dazu gehören das [[Sigmund-Freud-Museum]] (das sich im ehemaligen Wohnhaus des Begründers der Psychoanalyse in der Berggasse 19 befindet) die [[Volksoper]] Wien (zweitgrößtes Opernhaus der Stadt, beliebt für Operetten & Musicals), die [[Servitenkirche]] & das [[Servitenviertel]] (französisch geprägtes Flair, Cafés & Boutiquen), die [[Strudlhofstiege]] (berühmte Jugendstil-Treppe, literarisch verewigt von Heimito von Doderer),  der [[Narrenturm]] (Europas ältestes psychiatrisches Gebäude, heute pathologisch-anatomisches Museumdie). sowie die [[Votivkirche]] (bedeutende neugotische Kirche), die [[Lichtentaler]] Pfarrkirche (Taufkirche von Franz Schubert), das Gebäude der [[Österreichischen]] Nationalbank (Gebäude im neoklassizistischen Stil,  in der Architektur der 1920er und 1930er Jahre), das [[Josephinum]] (bedeutendes medizinisches Museum in Wien, das zur Medizinischen Universität Wien gehört) und der [[Franz-Josephs-Bahnhof]]"}, {"kategorie": "", "text": "Der 9. Bezirk Alsergrund ist eine ruhige, elegante und gebildete Wohngegend mit starker medizinischer und wissenschaftlicher Prägung. Er vereint Kultur, Geschichte und Lebensqualität auf hohem Niveau und ist besonders beliebt bei Menschen, die die Nähe zur Innenstadt, aber nicht deren Trubel suchen."}]'::jsonb, ''),
  ('poazellangossn', 'Poazellangossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Porzellangasse', '[{"kategorie": "allg.", "text": "bedeutende Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Franz-Josephs-Bahnhof]] im Norden bis zur [[Liechtensteinstraße]] im Süden und gehört zu den Hauptverkehrsstraßen des Bezirks"}, {"kategorie": "", "text": "Die Porzellangasse ist von einer abwechslungsreichen Architektur geprägt, die von prachtvollen Gründerzeitbauten über Jugendstilgebäude bis hin zu modernen Wohnhäusern reicht. Viele der Gebäude sind gut erhalten und stehen unter Denkmalschutz, was der Straße ihren historischen Charme verleiht."}]'::jsonb, ''),
  ('lazarettgossn', 'Lazarettgossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Lazarettgasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die sich von der [[Währinger]] Straße bis zur [[Alser]] Straße erstreckt\""}, {"kategorie": "", "text": "Die Lazarettgasse erhielt ihren Namen aufgrund des ehemaligen Militärlazaretts, das sich in der Nähe befand. Der Alsergrund, und damit auch die Lazarettgasse, war seit dem 18. Jahrhundert ein bedeutendes Zentrum der medizinischen Versorgung und Ausbildung in Wien. Zahlreiche Krankenhäuser, Kliniken und medizinische Institute wurden in diesem Bereich gegründet, was der Straße und der Umgebung ihre besondere Bedeutung verlieh"}, {"kategorie": "", "text": "Entlang der Lazarettgasse befinden sich mehrere Gebäude im Stil des Wiener [[Historismus]] und der [[Gründerzeit]], die teilweise noch aus dem 19. Jahrhundert stammen. Einige dieser Gebäude sind Teil der medizinischen Universitätsinfrastruktur und haben eine lange Geschichte als Orte der Forschung und Lehre"}]'::jsonb, ''),
  ('josephinum', 'Josephinum', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Josephinum', '[{"kategorie": "allg.", "text": "\"bedeutendes medizinisches Museum in Wien, das zur Medizinischen Universität Wien gehört\""}, {"kategorie": "", "text": "Es befindet sich im 9. Wiener Gemeindebezirk ([[Alsergrund]]), an der [[Währinger]] Straße, und ist bekannt für seine umfangreiche Sammlung anatomischer Wachsmodelle sowie für seine historische Bedeutung in der medizinischen Ausbildung"}, {"kategorie": "", "text": "Das Josephinum wurde 1785 von [[Kaiser]] Joseph II. gegründet, nach dem es auch benannt ist. Es war ursprünglich als Ausbildungsstätte für Militärärzte geplant und sollte der medizinischen Ausbildung in der [[Habsburgermonarchie]] dienen. Die Gründung des Josephinums war Teil der umfassenden Reformen von Joseph II., der das Gesundheitswesen und die medizinische Ausbildung modernisieren wollte"}, {"kategorie": "", "text": "Das Gebäude wurde von dem berühmten Architekten Isidore Canevale im klassizistischen Stil entworfen. Es zeichnet sich durch seine symmetrische Fassade, den monumentalen [[Portikus]] und die klaren, einfachen Linien aus, die für den [[Klassizismus]] typisch sind"}, {"kategorie": "", "text": "Das Josephinum ist weltweit bekannt für seine Sammlung anatomischer Wachsmodelle. Diese Modelle wurden im späten 18. Jahrhundert in Florenz hergestellt und sind außergewöhnlich detailliert. Sie dienten der Ausbildung von Medizinstudenten und bieten noch heute einen faszinierenden Einblick in die menschliche Anatomie. Die Sammlung umfasst über 1.200 Modelle, die verschiedene Teile des menschlichen Körpers in großem Detail zeigen."}]'::jsonb, 'Wääringa Schdrossn'),
  ('coburgbastei', 'Coburgbastei', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Coburgbastei', '[{"kategorie": "allg.", "text": "kurze Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die parallel zum [[Parkring]] verläuft und nach dem [[Palais]] Coburg benannt ist, das an dieser Straße liegt"}, {"kategorie": "", "text": "Die Straße ist nach dem Palais Coburg benannt, einem der prächtigsten Ringstraßenpalais Wiens, das wiederum seinen Namen von der fürstlichen Familie Sachsen-Coburg und Gotha erhalten hat, die das Palais im 19. Jahrhundert erbauen ließ"}, {"kategorie": "", "text": "Die Coburgbastei liegt im Zentrum Wiens, in unmittelbarer Nähe wichtiger Sehenswürdigkeiten wie dem [[Stadtpark]] und dem [[Stephansdom]]. Sie ist relativ kurz und endet an der [[Seilerstätte]], einer weiteren historischen Straße der Inneren Stadt"}, {"kategorie": "", "text": "Der Name „Bastei“ verweist auf die historischen Festungsanlagen Wiens, die im 19. Jahrhundert abgetragen wurden, um Platz für die Ringstraße und die angrenzenden Gebäude zu schaffen. Die Coburgbastei liegt in einem Bereich, der einst Teil dieser Befestigungen war"}]'::jsonb, ''),
  ('schrudlhofschdiang', 'Schrudlhofschdiang', '', '', '', 'Wiener Denkmäler & steinerne Zeitzeugen', 'Studlhofstiege', '[{"kategorie": "allg.", "text": "bekannte Freitreppe im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie wurde 1910 fertiggestellt und verbindet die [[Liechtensteinstraße]] mit der Strudlhofgasse, nach der sie benannt ist"}, {"kategorie": "", "text": "Die Treppe wurde vom Architekten Theodor Johann Jaeger entworfen und ist ein Beispiel für die Wiener Architektur des Jugendstils"}, {"kategorie": "", "text": "Die Strudlhofstiege besteht aus mehreren Treppenläufen und Podesten, die von balustradengeschmückten Brüstungen flankiert werden. In ihrer Mitte befindet sich ein Brunnen mit einer Balustrade, die einen schönen Ausblick auf die umgebende Umgebung bietet"}, {"kategorie": "", "text": "Bekannt wurde die Strudlhofstiege auch durch den Roman \"Die Strudlhofstiege oder Melzer und die Tiefe der Jahre\" von Heimito von Doderer, der 1951 veröffentlicht wurde. Das Buch hat die Treppe zu einem literarischen Schauplatz gemacht und trägt zur kulturellen Bedeutung dieses Ortes bei."}]'::jsonb, ''),
  ('lichtnschdaaschdrossn', 'Lichtnschdaaschdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Liechtensteinstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie verläuft in nord-südlicher Richtung und erstreckt sich vom [[Franz-Josefs-Bahnhof]] im Norden bis zur [[Schottengasse]] im Süden, wo sie in den [[Schottenring]] übergeht"}, {"kategorie": "", "text": "Die Straße ist nach dem Fürstenhaus Liechtenstein benannt, das seit dem 17. Jahrhundert bedeutende Ländereien in Wien besaß und nach wie vor das nahegelegene [[Palais]] Liechtenstein und den [[Liechtensteinpark]] in der Umgebung besitzt"}, {"kategorie": "", "text": "Die Liechtensteinstraße ist geprägt von einer Mischung aus Wohnhäusern, Geschäftslokalen und historischen Gebäuden. Sie dient als wichtige Verbindungsachse innerhalb des Bezirks und ist auch ein Standort zahlreicher Einrichtungen wie Schulen, Büros und Geschäfte."}]'::jsonb, ''),
  ('bankgossn', 'Bankgossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Bankgasse', '[{"kategorie": "allg.", "text": "kurze, aber bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Bankgasse verbindet die [[Schottengasse]] im Norden mit der [[Freyung]] im Süden. Sie liegt in unmittelbarer Nähe zu einigen der prächtigsten barocken Paläste der Stadt, wie dem [[Palais]] Kinsky, dem [[Palais]] Harrach und dem [[Palais]] Liechtenstein (Stadtpalais)"}, {"kategorie": "", "text": "Die Bankgasse in Wien verdankt ihren Namen einem historischen Gebäude, das sich einst dort befand. Zwischen 1820 und 1822 wurde hier das Gebäude der k.k. privat Österreichisch-ungarischen Bank errichtet. Dieser Umstand war so prägend für die Straße, dass sie schließlich nach dieser Bank benannt wurde."}]'::jsonb, ''),
  ('krugaschdrossn', 'Krugaschdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Krugerstraße', '[{"kategorie": "allg.", "text": "\"Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die sich in unmittelbarer Nähe einiger bedeutender Sehenswürdigkeiten und historischer Gebäude Wiens befindet und Teil des dicht bebauten und kulturell reichen Zentrums der Stadt ist\""}, {"kategorie": "", "text": "Die Krugerstraße verläuft in Nord-Süd-Richtung und erstreckt sich zwischen dem [[Kärntner]] Ring im Süden und der [[Kärntner]] Straße im Norden, einer der bekanntesten Einkaufsstraßen Wiens. Sie liegt in der Nähe der [[Staatsoper]] und des [[Stephansdoms]], zwei der wichtigsten Wahrzeichen Wiens"}, {"kategorie": "", "text": "Die Krugerstraße ist nach Johann Baptist Kruger benannt, einem Wiener Bürger, der sich im 18. Jahrhundert durch seine Wohltätigkeit und sein Engagement für die Stadt hervorgetan hat."}]'::jsonb, ''),
  ('meidling', 'Meidling', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Meidling', '[{"kategorie": "wörtlich", "text": "\"Wien-Meidling\""}, {"kategorie": "", "text": "\"der zwölfte [[Hieb]]\" (= 12. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Meidling grenzt im Norden an den 5. Bezirk ([[Margareten]]) und den 6. Bezirk ([[Mariahilf]]), im Osten an den 10. Bezirk ([[Favoriten]]), im Süden an den 23. Bezirk ([[Liesing]]) und im Westen an den 13. Bezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Der Name Meidling tauchte erstmals im 12. Jahrhundert auf. Der Bezirk entwickelte sich aus mehreren kleineren Vororten, die 1892 zu einem eigenen Gemeindebezirk zusammengelegt wurden (darunter [[Meidling]], [[Gaudenzdorf]], [[Hetzendorf]], [[Altmannsdorf]] und [[Untermeidling]])"}, {"kategorie": "", "text": "Im 19. Jahrhundert erlebte Meidling einen starken Bevölkerungszuwachs, was zu einer raschen Urbanisierung führte. Das Gebiet wandelte sich von einer ländlich geprägten Vorstadt zu einem dicht besiedelten städtischen Bezirk"}, {"kategorie": "", "text": "Der Bezirk ist ein vielfältiger, urbaner Stadtteil, der sowohl Wohn- als auch Gewerbegebiete umfasst und eine reiche historische sowie kulturelle Tradition hat. Heute ist Meidling ein klassischer Wiener „Mischbezirk“ mit Arbeitergeschichte und aufstrebenden Wohnvierteln, sowie auch zahlreichen Altbauten und [[Gemeindebauten]] aus dem [[Roten]] Wien"}, {"kategorie": "", "text": "Meidling ist ein lebendiger, vielschichtiger Bezirk, der Wiener Geschichte, multikulturelles Leben und stadtnahe Wohnqualität miteinander verbindet. Er ist ein authentischer Wiener Arbeiterbezirk, der sich aktuell zu einem modernen, urbanen Wohnviertel mit Zukunft entwickelt"}]'::jsonb, ''),
  ('hiitzing', 'Hiitzing', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Hietzing', '[{"kategorie": "wörtlich", "text": "\"Wien-Hietzing\""}, {"kategorie": "", "text": "\"der dreizehnte [[Hieb]]\" (= 13. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Hietzing ist einer der grünen und prestigeträchtigen Bezirke im Westen Wiens. Er ist bekannt für seine historischen Villen, weitläufigen Grünflächen und die Nähe zum [[Schloss]] Schönbrunn. Hietzing gilt als ein gehobenes Wohngebiet und verbindet städtisches Leben mit ländlichem Charme"}, {"kategorie": "hist.", "text": "Hietzing wurde im 12. Jahrhundert erstmals urkundlich erwähnt und entwickelte sich von einem kleinen Dorf zu einem beliebten Wohnort für den Wiener Adel. Seine Blütezeit erlebte der Bezirk im 19. Jahrhundert, als zahlreiche Villen und Landhäuser errichtet wurden"}, {"kategorie": "", "text": "Der Bezirk wurde 1892 als eigenständiger Bezirk nach Wien Wien eingemeindet. Die Geschichte von Hietzing ist eng mit dem [[Schloss]] Schönbrunn verbunden, das lange Zeit als Sommerresidenz der [[Habsburger]] diente"}, {"kategorie": "", "text": "Die bekanntesten [[Grätzln]] des Bezirks sind [[Alt-Hietzing]] (historischer Ortskern, Cafés, Villen, Nähe zu Schloss Schönbrunn), [[Ober-]] und Unter St. Veit (ruhige Wohnviertel mit Hanglage), [[Speising]] (traditioneller Ortsteil mit Spitälern und Wohnsiedlungen), [[Lainz]] (Villengegend, [[Lainzer]] Tiergarten), [[Hacking]] (waldnahes Nobelviertel), sowie [[Auhof]] und [[Lainzerbach]] (am westlichen Stadtrand, naturbelassen)"}, {"kategorie": "", "text": "Hietzing ist Wiens eleganter, grüner Villenbezirk mit reicher kaiserlicher Geschichte, einer gehobenen Wohnstruktur und exzellenter Lebensqualität. Wer Ruhe, Natur und historische Umgebung sucht, findet hier einen der lebenswertesten Stadtteile Österreichs – mit direkter Anbindung an die Wiener Innenstadt."}]'::jsonb, ''),
  ('penzing', 'Penzing', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Penzing', '[{"kategorie": "wörtlich", "text": "\"Wien-Penzing\""}, {"kategorie": "", "text": "\"der vierzehnte [[Hieb]]\" (= 14. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Penzing liegt im Westen der Stadt Wien. Der Bezirk zeichnet sich durch seine Mischung aus städtischen und ländlichen Gebieten aus, die sowohl Wohnviertel als auch große Grünflächen umfassen"}, {"kategorie": "", "text": "Penzing wurde im Jahr 1892 als eigenständiger Bezirk gegründet und bietet eine Vielfalt an architektonischen Stilen, von historischen Villen und Gründerzeitbauten bis hin zu modernen Wohnanlagen"}, {"kategorie": "", "text": "Ein markantes Merkmal von Penzing ist die [[Otto-Wagner-Kirche]] am [[Steinhof]], eine bedeutende Jugendstilkirche, die von dem berühmten Architekten Otto Wagner entworfen wurde. Sie gilt als eines der wichtigsten Werke des Wiener Jugendstils"}, {"kategorie": "", "text": "Der Wienerwald erstreckt sich über einen großen Teil von Penzing und bietet zahlreiche Möglichkeiten für Outdoor-Aktivitäten wie Wandern, Radfahren und Spazierengehen"}, {"kategorie": "", "text": "Die bekanntesten Grätzeln des Bezirks sind heute [[Baumgarten]] (Geburtsort Gustav Klimts, historischer Vorortcharakter), [[Hütteldorf]] (bekannt für das [[Allianz]] Stadion des SK Rapid Wien und den [[Bahnhof]] Hütteldorf), [[Penzing]] (im engeren Sinn - dichter bewohnt, mit Straßenbahn und U-Bahn-Anschluss), [[Breitensee]] (klassisches Wohnviertel, viele [[Gemeindebauten]]), [[Hadersdorf-Weidlingau]] ([[Ha-Wei]] - fast schon ländlich, mit Kleingarten- und Siedlungscharakter) und [[Auhof]] (Einzelhandel, Verkehrsknotenpunkt, Freizeitfläche)"}, {"kategorie": "", "text": "Penzing ist der westlichste grüne Randbezirk Wiens, der urbane Infrastruktur mit ländlicher Lebensqualität verbindet. Mit seinen Jugendstiljuwelen, Villengebieten, Waldnähe und kulturellen Highlights ist Penzing ein idealer Ort für alle, die Natur, Kultur und Ruhe in Wien suchen – ohne auf gute Anbindung verzichten zu müssen"}]'::jsonb, 'Hea auf zum Benzn, I bin do ned da Pforra von Penzing!'),
  ('westbaunteata', 'Westbaunteata', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Westbahntheater', '[{"kategorie": "allg.", "text": "freies, kleines Theater in [[Wien-Rudolfsheim-Fünfhaus]] (15. Bezirk), in unmittelbarer Nähe des [[Westbahnhofs]] (Adresse: Felberstraße 108, 1150 Wien)"}, {"kategorie": "", "text": "Das Westbahntheater versteht sich als offenes, unabhängiges Sprechtheater, das sich durch einen experimentellen, gesellschaftskritischen und künstlerisch mutigen Zugang zu zeitgenössischen Stoffen und Klassikern auszeichnet. Es wurde 2011 gegründet, die Spielstätte hat lediglich 50 Sitzplätze"}, {"kategorie": "", "text": "Es ist das kulturelles Aushängeschild des Bezirks [[Rudolfsheim-Fünfhaus]] und Teil der „freien Theaterszene Wiens“. Typische Programmpunkte umfassen Gegenwartstheater, Neuinterpretationen klassischer Stoffe (z. B. Brecht, Büchner, Shakespeare), Gastspiele und Festivals, sowie Lesungen, Diskussionsformate und Performances."}]'::jsonb, ''),
  ('ottakring', 'Ottakring', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Ottakring', '[{"kategorie": "wörtlich", "text": "\"Wien-Ottakring\""}, {"kategorie": "", "text": "\"der sechzehnte [[Hieb]]\" (= 16. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Ottakring liegt westlich des Stadtzentrums von Wien und grenzt im Osten an den 7. Bezirk ([[Neubau]]), den 8. Bezirk ([[Josefstadt]]) und den 17. Bezirk ([[Hernals]]). Im Süden grenzt Ottakring an den 15. Bezirk ([[Rudolfsheim-Fünfhaus]]) und im Westen an den [[Wienerwald]]"}, {"kategorie": "", "text": "Ottakring wurde 1892 als eigener Bezirk in Wien eingegliedert, indem mehrere Vororte, darunter [[Ottakring]], [[Neulerchenfeld]] und (zeilweise) [[Breitensee]], zusammengefasst wurden. Die Geschichte des Gebiets reicht jedoch viel weiter zurück, bis ins Mittelalter"}, {"kategorie": "", "text": "Der Name Ottakring leitet sich wahrscheinlich vom althochdeutschen Personennamen „Otachar“ oder „Otakar“ ab, kombiniert mit der Endung „-ing“, die auf eine Siedlung eines Stammes oder Gefolges hinweist. Die erste urkundliche Erwähnung von Ottakring erfolgte im Jahr 1147, in einer Schenkungsurkunde des Stiftes Klosterneuburg. Zu dieser Zeit war Ottakring noch ein kleines Bauerndorf, gelegen zwischen dem Wienerwald im Westen und der damals kaum entwickelten Stadt Wien im Osten"}, {"kategorie": "", "text": "Im Laufe des Mittelalters entwickelte sich Ottakring zu einem Weinbau- und Landwirtschaftsdorf, das dem Stift Klosterneuburg abgabepflichtig war. Im 15. und 16. Jahrhundert litt die Gegend wiederholt unter Türkenkriegen, Bränden und Pestepidemien, was die Bevölkerungszahl stagnieren ließ. Um 1700 lebten im Dorf weniger als 1.000 Menschen"}, {"kategorie": "", "text": "Mit dem Aufkommen der Industrialisierung im 19. Jahrhundert erlebte Ottakring einen radikalen Wandel: Fabriken, Brauereien (z. B. die [[Ottakringer]] Brauerei, 1837 gegründet) und Ziegelleien entstanden. Durch die Nähe zur Stadt und die vergleichsweise niedrigen Bodenpreise wurde Ottakring ein Zuzugsgebiet für Arbeiter:innen, besonders aus Böhmen, Mähren, Ungarn und anderen Teilen der Habsburgermonarchie. Zwischen 1860 und 1900 vervielfachte sich die Bevölkerung. Die Infrastruktur wurde ausgebaut: Schulen, Straßen, Wasserleitungen und später auch Straßenbahnen entstanden"}, {"kategorie": "", "text": "Heute ist Ottakring ist einer der multikulturellsten Bezirke Wiens, mit einer hohen Zahl von Bewohnern aus verschiedenen Ländern und Kulturen. Diese Vielfalt spiegelt sich in der Gastronomie, den Geschäften und dem allgemeinen Lebensgefühl wider"}]'::jsonb, '16-er Blech'),
  ('brunnanmoakt', 'Brunnanmoakt', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Brunnenmarkt', '[{"kategorie": "allg.", "text": "einer der bekanntesten und längsten Straßenmärkte in Wien, der im 16. Wiener Gemeindebezirk ([[Ottakring]]) Liegt"}, {"kategorie": "", "text": "Der Brunnenmarkt verläuft entlang der Brunnengasse zwischen dem [[Yppenplatz]] im Norden und der [[Thaliastraße]] im Süden. Er ist etwa 1 Kilometer lang und zählt damit zu den längsten Straßenmärkten Europas"}, {"kategorie": "", "text": "Der Brunnenmarkt ist ein lebendiges Beispiel für die kulturelle Vielfalt Ottakrings. Hier treffen Menschen unterschiedlicher Herkunft aufeinander, und die verschiedenen Kulturen spiegeln sich sowohl im Warenangebot als auch in der Atmosphäre des Marktes wider."}]'::jsonb, ''),
  ('yppnplotz', 'Yppnplotz', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Yppenplatz', '[{"kategorie": "allg.", "text": "zentraler Platz im 16. Wiener Gemeindebezirk ([[Ottakring]])"}, {"kategorie": "", "text": "Er bildet das Herz des Viertels rund um den [[Brunnenmarkt]] und ist bekannt für seine lebendige Atmosphäre, multikulturelle Prägung und seine Rolle als kultureller und sozialer Treffpunkt"}, {"kategorie": "", "text": "Der Yppenplatz wurde nach dem österreichischen General Johann von Yppen benannt und entwickelte sich im Laufe des 19. und 20. Jahrhunderts zu einem wichtigen Treffpunkt im Bezirk Ottakring"}, {"kategorie": "", "text": "Der Yppenplatz ist heute ein lebendiger sozialer Treffpunkt für die multikulturelle Bevölkerung Ottakrings. Der Platz und die angrenzenden Straßen sind bekannt für ihre Vielfalt an Cafés, Bars, Restaurants und kleinen Läden, die kulinarische und kulturelle Angebote aus aller Welt präsentieren."}]'::jsonb, ''),
  ('thaliaschdrossn', 'Thaliaschdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Thaliastraße', '[{"kategorie": "allg.", "text": "eine der wichtigsten Verkehrs- und Einkaufsstraßen im 16. Wiener Gemeindebezirk ([[Ottakring]])"}, {"kategorie": "", "text": "Sie beginnt im Osten am [[Gürtel]] (nahe der U-Bahn-Station Thaliastraße der Linie U6) und verläuft in westlicher Richtung durch den gesamten Bezirk Ottakring bis zur Grenze des 16. Bezirks in Richtung 14. Bezirk ([[Penzing]])"}, {"kategorie": "", "text": "Die Thaliastraße entwickelte sich im 19. Jahrhundert zu einer bedeutenden Verkehrs- und Handelsstraße. Ursprünglich eine Vorstadtstraße, wuchs ihre Bedeutung mit der Industrialisierung und dem Bevölkerungszuwachs in Ottakring"}, {"kategorie": "", "text": "Der Name \"Thaliastraße\" geht auf die griechische Muse Thalia zurück, die Muse der Komödie und des Idylls. Dies spiegelt die kulturelle Bedeutung wider, die die Straße in der Vergangenheit hatte und teilweise bis heute hat."}]'::jsonb, ''),
  ('wuehaeminenbeag', 'Wühäminenbeag', '', '', '', 'Wiener Parks und Parkanlagen', 'Wilhelminenberg', '[{"kategorie": "allg.", "text": "Anhöhe im 16. Wiener Gemeindebezirk ([[Ottakring]]) und ein Teil des [[Wienerwalds]]"}, {"kategorie": "", "text": "Der Berg ist bekannt für seine malerische Landschaft, seine historischen Gebäude und seine Rolle als beliebtes Naherholungsgebiet in Wien. Der Wilhelminenberg erhebt sich etwa 449 Meter über dem Meeresspiegel und bietet eine ausgezeichnete Panoramasicht über Wien und die umliegenden Gebiete"}, {"kategorie": "", "text": "Der Wilhelminenberg wurde nach Erzherzogin Wilhelmine Amalie benannt, der Tochter von [[Kaiser]] Leopold II., die auf dieser Anhöhe 1903 den Bau des Schlosses Wilhelminenberg in Augtrag gab"}, {"kategorie": "", "text": "Aufgrund seiner Höhe und Lage ist der Wilhelminenberg einer der besten Aussichtspunkte in Wien. Vom Schloss Wilhelminenberg und anderen Aussichtspunkten aus kann man das Panorama der Stadt, den Wienerwald und bei klarem Wetter sogar die Alpen sehen. Die Umgebung des Wilhelminenbergs ist zudem auch bekannt für ihre zahlreichen [[Heurigen]] (traditionelle Wiener Weinschenken)"}]'::jsonb, ''),
  ('kongresspark', 'Kongresspark', '', '', '', 'Wiener Parks und Parkanlagen', 'Kongresspark', '[{"kategorie": "allg.", "text": "öffentliche Parkanlage im 16. Wiener Gemeindebezirk ([[Ottakring]]), in der Nähe des [[Wilhelminenbergs]]"}, {"kategorie": "", "text": "Der Kongresspark wurde in den 1920er Jahren als Teil eines größeren städtischen Projekts zur Schaffung von Wohnraum und Erholungsflächen für die Wiener Bevölkerung angelegt. Er wurde zeitgleich mit dem benachbarten [[Kongressbad]], einem der ältesten Freibäder Wiens, errichtet"}, {"kategorie": "", "text": "Der Name \"Kongresspark\" erinnert an den Wiener Kongress (1814–1815), eine bedeutende politische Veranstaltung in der Geschichte Europas, die in Wien stattfand"}, {"kategorie": "", "text": "Der Kongresspark ist heute ein wichtiger Erholungsort und ein wertvolles Stück urbaner Natur in Wien. Er bietet den Bewohnern Ottakrings und Besuchern eine Möglichkeit, dem Trubel der Stadt zu entfliehen und in einer gepflegten, historischen Parklandschaft zu entspannen. Der Park bleibt ein lebendiger und beliebter Treffpunkt, der das soziale und kulturelle Leben im 16. Bezirk bereichert."}]'::jsonb, ''),
  ('kongressbood', 'Kongressbood', '', '', '', 'Wiener Gemeindebauten', 'Kongressbad', '[{"kategorie": "allg.", "text": "öffentliches Freibad im 16. Wiener Gemeindebezirk ([[Ottakring]])"}, {"kategorie": "", "text": "Es gehört zu den ältesten und traditionsreichsten Freibädern in Wien und ist Teil eines größeren Freizeitareals, zu dem auch der benachbarte [[Kongresspark]] gehört"}, {"kategorie": "", "text": "Das Kongressbad wurde 1928 eröffnet, sein Name leitet sich vom benachbarten Kongresspark ab, der wiederum nach dem Wiener Kongress (1814–1815) benannt ist"}, {"kategorie": "", "text": "Das Kongressbad ist ein typisches Beispiel für die Architektur der 1920er Jahre und zeigt Elemente des Bauhausstils sowie des Funktionalismus. Trotz mehrerer Renovierungen und Modernisierungen hat das Bad viel von seinem historischen Charme bewahrt und bietet eine nostalgische Atmosphäre, die an die frühen Tage des Wiener Schwimmens erinnert"}, {"kategorie": "", "text": "Das Kongressbad verfügt über mehrere Schwimmbecken, die von großzügigen Liegewiesen umgeben sind. Zusätzlich zu den Schwimmbecken bietet das Bad zahlreiche Freizeiteinrichtungen, darunter Wasserrutschen, Sprungtürme, Spielplätze für Kinder, Tischtennisplatten und einen Beachvolleyballplatz."}]'::jsonb, ''),
  ('heanois', 'Heanois', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Hernals', '[{"kategorie": "wörtlich", "text": "\"Wien-Hernals\""}, {"kategorie": "", "text": "\"der siebzehnte [[Hieb]]\" (= 17. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Er liegt im Nordwesten Wiens und ist bekannt für seine vielfältige Mischung aus städtischem Leben und ländlichen Elementen. Hernals grenzt im Osten an die Bezirke [[Josefstadt]] (8. Bezirk), [[Alsergrund]] (9. Bezirk) und [[Währing]] (18. Bezirk), im Süden an [[Ottakring]] (16. Bezirk) und im Westen und Norden an die Wienerwaldgebiete, die bereits zu Niederösterreich gehören. Durch seine Lage am Rand des [[Wienerwalds]] ist der Bezirk stark von grünen Flächen und Hügeln geprägt, was ihn zu einem beliebten Wohngebiet mit hoher Lebensqualität macht"}, {"kategorie": "", "text": "Hernals hat eine lange Geschichte, die bis ins Mittelalter zurückreicht. Ursprünglich war das Gebiet eine Ansammlung von Dörfern, die im Laufe der Jahrhunderte allmählich zur Stadt Wien hinwuchsen. Der Name \"Hernals\" wurde erstmals im 12. Jahrhundert urkundlich erwähnt. Hernals wurde im 19. Jahrhundert, genauer 1892, zusammen mit anderen Vororten wie [[Dornbach]] und [[Neuwaldegg]] in Wien eingemeindet und zum 17. Bezirk erklärt"}, {"kategorie": "", "text": "In der Habsburgerzeit war Hernals ein beliebter Kurort, bekannt für seine Heilquellen und Kuranlagen. Dies lockte zahlreiche Besucher aus der Stadt an, was die Entwicklung des Bezirks weiter vorantrieb. Spuren dieser Vergangenheit sind noch heute in Form von alten Villen und Kuranlagen zu finden"}, {"kategorie": "", "text": "Der Bezirk Hernals ist architektonisch vielfältig, was sich in einer Mischung aus [[Gründerzeitbauten]], klassischen [[Wiener]] Zinshäusern und modernen Wohnanlagen zeigt. In den zentralen Bereichen von Hernals findet man viele Gebäude aus der Zeit der Jahrhundertwende, die durch ihren historischen Charme und ihre architektonische Detailverliebtheit bestechen"}, {"kategorie": "", "text": "Der Bezirk ist auch für seine Kirchen und historischen Bauwerke bekannt, darunter die [[Kalvarienbergkirche]], die in der Nähe des [[Elterleinplatzes]] steht, einem der zentralen Plätze des Bezirks. Die Kirche und der dazugehörige [[Kalvarienbergmarkt]] sind wichtige kulturelle Zentren in Hernals"}, {"kategorie": "", "text": "Hernals bietet eine Fülle von Grünflächen und Erholungsmöglichkeiten, die durch die Nähe zum Wienerwald ergänzt werden. Zu den bekanntesten Naturgebieten gehört der [[Schwarzenbergpark]] in Neuwaldegg, der als ältester Landschaftsgarten Österreichs gilt. Dieser Park ist ein beliebtes Ausflugsziel für Wanderer und Naturliebhaber und bietet zahlreiche Wanderwege, die tief in den Wienerwald führen"}]'::jsonb, ''),
  ('schwoaznbeagpark', 'Schwoaznbeagpark', '', '', '', 'Wiener Parks und Parkanlagen', 'Schwarzenbergpark', '[{"kategorie": "allg.", "text": "großer Landschaftspark im 17. Wiener Gemeindebezirk ([[Hernals]])"}, {"kategorie": "", "text": "Er befindet sich im Stadtteil [[Neuwaldegg]] und gilt als der älteste Landschaftsgarten Österreichs"}, {"kategorie": "", "text": "Der Schwarzenbergpark wurde im 18. Jahrhundert von der Adelsfamilie Schwarzenberg angelegt, die in dieser Region große Ländereien besaß. Der Park wurde um das Jahr 1780 nach englischem Vorbild als Landschaftsgarten gestaltet, was zu dieser Zeit eine Neuheit in der Gartengestaltung darstellte. Der englische Landschaftsstil zeichnete sich durch weitläufige, naturnahe Gestaltungen mit sanft geschwungenen Wegen, Wiesenflächen und Baumgruppen aus"}, {"kategorie": "", "text": "Der Park war ursprünglich Teil des Schlosses Neuwaldegg, das im Besitz der Familie Schwarzenberg war. Der Garten diente als repräsentatives Element des Schlosses und als Ort der Erholung für die Familie und ihre Gäste. Im Laufe der Jahrhunderte wurde der Park immer wieder erweitert und gestaltet, blieb aber in seinem Grundkonzept als Landschaftsgarten erhalten"}, {"kategorie": "", "text": "Der Schwarzenbergpark ist ein typisches Beispiel für einen englischen Landschaftsgarten. Er zeichnet sich durch seine großzügigen, natürlichen Landschaftsformen aus, die durch Gehölze, Wiesen und Wasserflächen betont werden. Der Park enthält einige architektonische Elemente, die als Blickpunkte dienen, wie zum Beispiel Denkmäler, Brücken und künstliche Ruinen"}, {"kategorie": "", "text": "Heute ist der Schwarzenbergpark ein wichtiges Naherholungsgebiet für die Bewohner Wiens. Der Park ist ideal für Spaziergänge, Jogging, Wandern und Radfahren geeignet. Durch seine Lage am Rande des Wienerwalds ist er auch ein Ausgangspunkt für längere Wanderungen in die umliegenden Waldgebiete. Im Winter wird der Park häufig zum Rodeln genutzt."}]'::jsonb, ''),
  ('neuwoidegg', 'Neuwoidegg', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Neuwaldegg', '[{"kategorie": "allg.", "text": "Stadtteil im 17. Wiener Gemeindebezirk ([[Hernals]]), der sich am nordwestlichen Stadtrand von Wien befindet, direkt am Fuße des [[Wienerwalds]]"}, {"kategorie": "", "text": "Die Geschichte von Neuwaldegg ist eng mit dem [[Schloss]] Neuwaldegg verbunden. Der Stadtteil entstand rund um das Schloss, das im 17. Jahrhundert von Graf Theodor von Strattmann erbaut wurde. Im Laufe der Jahrhunderte entwickelte sich Neuwaldegg von einer ländlichen Siedlung zu einem beliebten Wohngebiet für wohlhabende Wiener Bürger, die die Ruhe und die Nähe zur Natur schätzten"}, {"kategorie": "", "text": "Neben dem Schloss Neuwaldegg und dem dazugehörigen Schlosspark gibt es in Neuwaldegg einige historische Gebäude und Villen, die den Charme des Stadtteils unterstreichen. Die Architektur spiegelt den Geschmack der wohlhabenden Wiener Gesellschaft des 18. und 19. Jahrhunderts wider, mit prächtigen Bauten und großzügigen Grünanlagen"}, {"kategorie": "", "text": "Eine weitere Sehenswürdigkeit ist der [[Schwarzenbergpark]], der im 18. Jahrhundert von der Familie Schwarzenberg angelegt wurde und als einer der ältesten Landschaftsgärten Österreichs gilt. Dieser Park grenzt direkt an Neuwaldegg und bietet weitere Möglichkeiten für Erholung und Naturerlebnisse."}]'::jsonb, ''),
  ('doanboch', 'Doanboch', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Dornbach', '[{"kategorie": "allg.", "text": "Stadtteil im 17. Wiener Gemeindebezirk ([[Hernals]]) am westlichen Stadtrand Wiens (am Rande des [[Wienerwalds]]), der für seine malerische Lage, seine Geschichte sowie seine Villen und Grünanlagen bekannt. Dornbach ist ein traditionell bürgerliches Wohngebiet, das sich durch eine ruhige, fast dörfliche Atmosphäre auszeichnet"}, {"kategorie": "", "text": "Dornbach erstreckt sich entlang des Dornbaches, eines kleinen Bachs, der dem Stadtteil seinen Namen gegeben hat. Die geografische Lage von Dornbach ist geprägt durch die sanften Hügel des Wienerwalds, die das Gebiet umgeben"}, {"kategorie": "", "text": "Die Geschichte von Dornbach reicht weit zurück, bis ins Mittelalter. Ursprünglich war Dornbach ein kleines Bauerndorf, das im Laufe der Jahrhunderte langsam in die Stadt Wien integriert wurde. Bis ins 19. Jahrhundert hinein behielt Dornbach einen ländlichen Charakter bei, mit Weinbergen und landwirtschaftlichen Flächen"}, {"kategorie": "", "text": "Im 19. Jahrhundert entwickelte sich Dornbach zunehmend zu einem Wohngebiet für wohlhabende Bürger, die hier Sommerresidenzen und Villen errichteten. Die Anbindung an Wien wurde durch den Bau von Straßen und später der Straßenbahn verbessert, was Dornbach noch attraktiver machte. Bis heute zeugen viele Villen und historische Gebäude von der Blütezeit des Stadtteils im 19. Jahrhundert"}, {"kategorie": "", "text": "Ein bedeutendes architektonisches Wahrzeichen Dornbachs ist die [[Pfarrkirche]] Dornbach, die im neugotischen Stil erbaut wurde und das Zentrum des Stadtteils bildet. Die Kirche stammt aus dem 19. Jahrhundert und ist ein wichtiges religiöses und kulturelles Zentrum der Gemeinde"}, {"kategorie": "", "text": "Eine weitere Sehenswürdigkeit ist der [[Friedhof]] Dornbach, ein kleiner, historischer Friedhof, auf dem einige bekannte Persönlichkeiten, darunter der österreichische Komponist Carl Michael Ziehrer, beerdigt sind."}]'::jsonb, ''),
  ('obalaa', 'Obalaa', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Oberlaa', '[{"kategorie": "allg.", "text": "\"Stadtteil im 10. Wiener Gemeindebezirk ([[Favoriten]]) an der südlichen Stadtgrenze von Wien\""}, {"kategorie": "", "text": "Oberlaa ist vor allem bekannt für seine Thermalquellen (siehe [[Therme Wien]]), den weitläufigen Kurpark (siehe \"Kurpark Oberlaa\") und seine [[Weinkultur]], die von zahlreichen [[Heurigen]] (Weinschenken) bewahrt wird"}, {"kategorie": "", "text": "Die Lage am Rande der Stadt  verleiht Oberlaa einen ländlichen Charme, der trotz der fortschreitenden Urbanisierung erhalten geblieben ist"}, {"kategorie": "", "text": "Die Geschichte von Oberlaa reicht bis ins Mittelalter zurück. Der Name „Oberlaa“ wird erstmals im 12. Jahrhundert urkundlich erwähnt. Das Gebiet war lange Zeit ein kleines, landwirtschaftlich geprägtes Dorf, das für seinen Weinbau bekannt war. Der Weinbau hat in Oberlaa eine lange Tradition und ist bis heute ein wichtiger Bestandteil der lokalen Kultur"}, {"kategorie": "", "text": "Im 19. Jahrhundert begann Oberlaa, sich zu einem Kurort zu entwickeln, nachdem die heilenden Eigenschaften der Thermalquellen entdeckt wurden. Diese Entwicklung führte zur Errichtung von Kureinrichtungen und machte den Ort zu einem beliebten Ziel für Erholungssuchende. Mit der Eingemeindung in die Stadt Wien im Jahr 1938 begann eine neue Phase in der Geschichte Oberlaas, die durch verstärkte Urbanisierung und den Ausbau der Infrastruktur gekennzeichnet ist"}, {"kategorie": "", "text": "Ein weiteres historisches Highlight ist die [[Pfarrkirche]] Oberlaa, eine barocke Kirche, die im 18. Jahrhundert erbaut wurde und sich durch ihre schöne Architektur und ihren historischen Wert auszeichnet."}]'::jsonb, ''),
  ('untalaa', 'Untalaa', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Unterlaa', '[{"kategorie": "allg.", "text": "Stadtteil im 10. Wiener Gemeindebezirk ([[Favoriten]]), der im südöstlichen Teil von Wien, nahe der Stadtgrenze, liegt"}, {"kategorie": "", "text": "Es ist ein historisch geprägtes Gebiet, das bis heute einen ländlichen Charakter bewahrt hat, obwohl es zunehmend in die städtische Struktur Wiens integriert wurde. Unterlaa ist vor allem für seine landwirtschaftlichen Flächen, seine Nähe zur Natur und seine ruhige Wohnlage bekannt"}, {"kategorie": "", "text": "Der Stadtteil liegt entlang des Liesingbachs, einem kleinen Fluss, der durch das Gebiet fließt und zur Entstehung von Auwäldern und Feuchtwiesen beigetragen hat. Diese natürliche Umgebung verleiht Unterlaa einen besonderen Reiz und macht es zu einem beliebten Ort für Natur- und Erholungssuchende"}, {"kategorie": "", "text": "Die Geschichte von Unterlaa reicht bis ins Mittelalter zurück. Erste urkundliche Erwähnungen stammen aus dem 12. Jahrhundert. Ähnlich wie Oberlaa war Unterlaa lange Zeit ein kleines, landwirtschaftlich geprägtes Dorf, das sich durch den Anbau von Getreide, Wein und Gemüse auszeichnete"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte blieb Unterlaa relativ unverändert, obwohl es zunehmend von der Urbanisierung Wiens beeinflusst wurde. Der Anschluss an Wien erfolgte formell im Jahr 1938, als Unterlaa im Zuge der Eingemeindung zu einem Teil des 10. Bezirks, Favoriten, wurde"}, {"kategorie": "", "text": "Eine zentrale Sehenswürdigkeit ist die \"Kirche St. Johann zu Unterlaa\" ([[Johanneskirche]]), eine römisch-katholische Kirche, die als eine der ältesten Kirchen des heutigen Wien gilt, da die hochmittelalterlichen Bauteile mindestens in das erste Drittel des 11. Jahrhunderts zurückreichen könnten. St. Johann zu Unterlaa ist eine Filialkirche der [[Pfarrkirche]] Oberlaa."}]'::jsonb, ''),
  ('johanneskiachn', 'Johanneskiachn', '', '', '', 'Wiener Kirchen & Gotteshäuser', 'Johanneskirche', '[{"kategorie": "wörtlich, kurz für", "text": "\"Kirche St. Johann zu Unterlaa\" (eine römisch-katholische Kirche, die sich im Stadtteil [[Unterlaa]] im 10. Wiener Gemeindebezirk [[[Favoriten]]] befindet)"}, {"kategorie": "", "text": "Sie wird als eine der ältesten Kirchen des heutigen Wien betrachtet, da die hochmittelalterlichen Bauteile mindestens in das erste Drittel des 11. Jahrhunderts zurückreichen könnten. St. Johann zu Unterlaa ist eine Filialkirche der [[Pfarrkirche]] Oberlaa"}, {"kategorie": "", "text": "An der Stelle der heutigen Kirche stand vermutlich ein römischer Tempel aus Holz auf einem Steinfundament. Mönche errichteten später das erste Kirchlein, um den heidnischen Tempel mit christlichem Geist zu überlagern"}, {"kategorie": "", "text": "Die Kirche kam 1272 in den Besitz des Johanniterordens und wurde umgebaut. 1683 während der Zweiten Wiener Türkenbelagerung zerstört, wurde sie 1686 wieder aufgebaut"}, {"kategorie": "", "text": "Die Kirche ist eine Chorturmkirche mit einem Langhaus und einem achteckigen Chorturm. Neben der Kirche steht eine Heilig-Grab-Kapelle, die um 1700 erbaut wurde. Ausgrabungen in der Umgebung zeugen von einer langen Besiedlungsgeschichte, die bis in die Urzeit zurückreicht."}]'::jsonb, ''),
  ('waehring', 'Währing', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Währing', '[{"kategorie": "wörtlich", "text": "\"Wien-Währing\""}, {"kategorie": "", "text": "\"der achtzehnte [[Hieb]]\" (= 18. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Währing liegt im nordwestlichen Teil der Stadt Wien. Der Bezirk ist bekannt für seine grünen Wohngegenden, historischen Villen, bedeutenden Bildungseinrichtungen und eine angenehme Mischung aus städtischem Leben und naturnaher Erholung"}, {"kategorie": "", "text": "Währing erstreckt sich vom Rand des [[Wienerwalds]] bis hin zur Bezirksgrenze des 9. Bezirks ([[Alsergrund]]) und grenzt auch an den 19. Bezirk ([[Döbling]]) und an den 17. Bezirk ([[Hernals]])"}, {"kategorie": "", "text": "Erstmals urkundlich erwähnt wurde „Währing“ um das Jahr 1170 (als „Werig“). Ursprünglich ländlich geprägt, vor allem durch Weinbau, entwickelte sich Währing im 18. und 19. Jahrhundert zum Sommerfrische-Ort der Wiener Oberschicht. 1892 wurde Währing im Zuge der Stadterweiterung nach Wien eingemeindet und seitdem kontinuierlich zu einem gehobenen Wohn- und Villenbezirk ausgebaut. Bedeutende Persönlichkeiten wie Franz Schubert, Friedrich Torberg, Johannes Brahms und Heimito von Doderer hatten hier ihre Wurzeln oder Wirkungsstätten"}, {"kategorie": "", "text": "Der Bezirk zeichnet sich durch eine Mischung aus historischen [[Gründerzeitgebäuden]], modernen Wohnhäusern und Villen aus. Besonders in [[Gersthof]] und [[Pötzleinsdorf]] finden sich viele repräsentative Villen und gepflegte Altbauwohnungen"}, {"kategorie": "", "text": "Derà Währinger Friedhof, der heute nicht mehr als Friedhof genutzt wird, war einst die Ruhestätte von bedeutenden Persönlichkeiten wie Ludwig van Beethoven und Franz Schubert, deren Gräber später auf den [[Zentralfriedhof]] verlegt wurden"}]'::jsonb, ''),
  ('doebling', 'Döbling', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Döbling', '[{"kategorie": "wörtlich", "text": "\"Wien-Döbling\""}, {"kategorie": "", "text": "\"der neunzehnte [[Hieb]]\" (= 19. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Döbling zählt zu den bekanntesten und gehobensten Bezirken Wiens. Er liegt im Nordwesten der Stadt, am Rand des Wienerwalds, und ist durch eine Mischung aus urbanem Wohnraum, historischen Villenvierteln, Weinbaugebieten und weitläufigen Grünflächen geprägt"}, {"kategorie": "", "text": "Döbling erstreckt sich von den Ufern der [[Donau]] bis in die hügeligen Ausläufer des [[Wienerwalds]]. Durch diese Lage bietet der Bezirk eine Kombination aus städtischem Leben und naturnahen Erholungsmöglichkeiten"}, {"kategorie": "", "text": "Döbling grenzt an die Bezirke [[Alsergrund]] (9. Bezirk), [[Währing]] (18. Bezirk), [[Hernals]] (17. Bezirk) und [[Floridsdorf]] (21. Bezirk) sowie an die niederösterreichische Stadt Klosterneuburg."}, {"kategorie": "", "text": "Döbling ist stark vom Weinbau geprägt, und die zahlreichen [[Heurigenlokale]] sind beliebte Treffpunkte für Einheimische und Touristen. Die Weinberge bieten darüber hinaus schöne Wanderwege und Ausblicke über Wien"}, {"kategorie": "", "text": "Die Geschichte Döblings reicht bis in die Römerzeit zurück, als sich in der Gegend von Heiligenstadt eine römische Siedlung befand. Im Mittelalter bestanden in der heutigen Bezirksfläche mehrere eigenständige Dörfer wie Oberdöbling, Unterdöbling, Grinzing und Nussdorf, die stark vom Weinbau geprägt waren. Döbling wurde 1892 als eigenständiger Bezirk durch die Zusammenlegung mehrerer Vororte geschaffen und besteht heute aus folgenden Bezirksteilen:  [[Grinzing]], [[Sievering]], [[Neustift]] am Walde, [[Salmannsdorf]], [[Nussdorf]], [[Heiligenstadt]], [[Oberdöbling]], [[Unterdöbling]], [[Kahlenbergerdorf]]"}, {"kategorie": "", "text": "Döbling ist heute ein wohlhabender und naturnaher Bezirk Wiens, der urbane Lebensqualität mit ländlichem Flair verbindet. Geprägt von eleganten Villen, traditionsreichen Heurigen und ausgedehnten Grünflächen wie dem Wienerwald, gilt er als eine der begehrtesten Wohngegenden der Stadt."}]'::jsonb, ''),
  ('brigittenau', 'Brigittenau', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Brigittenau', '[{"kategorie": "wörtlich", "text": "\"Wien-Brigittenau\""}, {"kategorie": "", "text": "\"der zwanzigste [[Hieb]]\" (= 20. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Er liegt im nördlichen Teil von Wien, zwischen dem [[Donaukanal]] und der [[Donau]]. Der Bezirk ist durch seine urbane Struktur, historische Entwicklung und multikulturelle Bevölkerung geprägt"}, {"kategorie": "", "text": "Brigittenau ist einer der jüngeren Bezirke Wiens, der sich aus früheren Teilen der [[Leopoldstadt]] (2. Bezirk) entwickelt hat, mit welchem gemeinsam die Brigittenau im Volksmund auch als \"Insel\" bezeichnet wird (aufgrund deren Lage zwischen Donau und Donaukanal)"}, {"kategorie": "", "text": "Brigittenau grenzt im Süden an die [[Leopoldstadt]] (2. Bezirk), im Westen an den [[Alsergrund]] (9. Bezirk) und im Norden an [[Floridsdorf]] (21. Bezirk), das durch die Donau getrennt ist"}, {"kategorie": "", "text": "Der Bezirk wurde 1900 gegründet, nachdem das Gebiet zuvor Teil der Leopoldstadt war. Die Urbanisierung des Gebiets begann im 19. Jahrhundert, als die Donauregulierung Wien vor Überschwemmungen schützte und Bauland freimachte"}, {"kategorie": "", "text": "Die Brigittenau war ursprünglich eine von Überschwemmungen geprägte Aulandschaft zwischen Donau und Donaukanal und wurde erst im 17. und 18. Jahrhundert schrittweise besiedelt. Ihren Namen erhielt sie von der 1654 errichteten Brigittakapelle, benannt nach der heiligen Brigitta. Mit der Donauregulierung im 19. Jahrhundert und dem starken Bevölkerungswachstum während der Industrialisierung entwickelte sich die Brigittenau rasch zu einem dicht bebauten Arbeiterbezirk. Seither prägt eine Mischung aus [[Gemeindebauten]], Industriegeschichte und multikultureller Vielfalt das Bild des Bezirks"}]'::jsonb, ''),
  ('fluaridsduaf', 'Fluaridsduaf', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Floridsdorf', '[{"kategorie": "wörtlich", "text": "\"Wien-Floridsdorf\""}, {"kategorie": "", "text": "\"der einundzwanzigste [[Hieb]]\" (= 21. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Floridsdorf liegt nördlich der Donau und ist über die [[Floridsdorfer]] Brücke, die [[Nordbrücke]], sowie die U-Bahnlinie U6 mit dem Stadtzentrum verbunden. Der Bezirk ist durchzogen der [[Donauinsel]] (teils zu Floridsdorf gehörig), der [[Alten]] Donau (einem beliebten Freizeitgewässer), dem Marchfeldkanal und weiteren Grünräumen"}, {"kategorie": "", "text": "Floridsdorf entstand ursprünglich durch Zusammenlegung mehrerer Dörfer, darunter Floridsdorf, [[Jedlesee]] und [[Strebersdorf]], und ist nach dem Klosterneuburger Propst Floridus Leeb (18. Jh.) benannt, der die Gegend erschließen ließ. 1904 wurde Floridsdorf nach Wien eingemeindet, in der Zeit des Zweiten Weltkriegs stark zerstört und danach wieder aufgebaut.  5. In Floridsdorf gibt es zahlreiche [[Heurige]] (Weinschenken) mit Ausblick auf die Weinberge und Richtung Donau, insbesondere in den Bezirksteilen [[Stammersdorf]] und [[Strebersdorf]]"}, {"kategorie": "", "text": "Heute hat Floridsdorf ca. 170.000 Einwohner und ist mit einer Fläche von 44,5 km² der viertgrößter Bezirk Wiens. Der Bezirk ist geprägt von Kontrasten zwischen Stadt und Land: Industrie, Urbanität, Wohnbau, Donauufer, Heurigenkultur und Weinberge treffen hier aufeinander. Mit guter Infrastruktur und großer Fläche zählt Floridsdorf zu den vielfältigsten Bezirken Wiens – ein Stadtteil im Wandel mit starkem Wachstum."}]'::jsonb, ''),
  ('donauschdodt', 'Donauschdodt', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Donaustadt', '[{"kategorie": "wörtlich", "text": "\"Wien-Donaustadt\""}, {"kategorie": "", "text": "\"der zweiundzwanzigste [[Hieb]]\" (= 22. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Donaustadt liegt östlich der Donau, umfasst Teile der [[Donauinsel]], die [[Lobau]], neue Stadtteile wie die [[Seestadt]] sowie zahlreiche Dörfer, die im Laufe der Zeit eingemeindet wurden, darunter Kagran, Kaisermühlen, Essling, Stadlau, Aspern, Hirschstetten und Breitenlee. Donaustadt grenzt an die Wiener Bezirke [[Floridsdorf]] (21.), [[Leopoldstadt]] (2.), [[Simmering]] (11.), sowie an das Bundesland Niederösterreich"}, {"kategorie": "", "text": "Bis ins 19. Jahrhundert befanden sich in Donaustadt hauptsächlich landwirtschaftlich geprägte Dörfer mit Mühlen, Feldern und Weingärten. 1904 erfolgten die ersten Eingemeindungen nach Wien (z. B. Kaisermühlen, Kagran), und 1954 wurde die Donaustadt als 22. Bezirk offiziell gegründet (durch Abspaltung von Floridsdorf). Seither ist die Donaustadt gilt als einer der dynamischsten Entwicklungsräume Wiens"}, {"kategorie": "", "text": "Mit einer Fläche von ca. 102,3 km² ist die Donaustadt der flächenmäßig größte Bezirk Wiens, seine Einwohnerzahl beträgt ca. 210.000. Trotz stetig wachsender Urbanisierung besitzt die Donaustadt große Natur- und Freizeitflächen wie z.B. die [[Lobau]] (Teil des Nationalparks Donau-Auen – geschützte Au-Landschaft), die [[Donauinsel]] (Freizeit, Sport, Erholung), die [[Alte]] Donau (Badegewässer, Bootsverleih), die [[Hirschstettner]] Blumengärten sowie die Badeteiche [[Süßenbrunn]], [[Hirschstetten]], [[Breitenlee]] und den [[Donaupark]] (Grenzlage 22./21. Bezirk)"}, {"kategorie": "", "text": "In der Donaustadt treffen Donauufer & Wolkenkratzer, Nationalpark & U-Bahn, Heurige & Hochhäuser, alte Dorfkerne & moderne Architektur aufeinander. Somit ist die Donaustadt ist Natur-, Wohn- und Zukunftsbezirk zugleich – und prägt Wiens Entwicklung maßgeblich mit."}]'::jsonb, ''),
  ('indianakropfn', 'Indianakropfn', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Indianerkrapfen', '[{"kategorie": "wörtlich", "text": "\"Krapfen zu Ehren der Indianer\" (von einem Wiener Zuckerbäcker 1820 kreierte Mehlspeise zu Ehren zweier damals in Wien gastierender indischer Artisten [\"die berühmten Indianer\" Thomas Bauleau und Kurom Balahia Titecan])"}, {"kategorie": "Kulinarik", "text": "Süßspeise aus zwei ausgehöhlten Biskuit-Halbkugeln, die mit gezuckertem, vanilliertem Schlagobers (Creme Chantilly) zusammengesetzt, aprikotiert und mit Schokolade überzogen werden"}, {"kategorie": "", "text": "[[Indianer mit Schlag]], (Deutschland): \"Mohrenkopf\", \"Schokokuss\""}]'::jsonb, 'I kunntad mi in gaunzn Toog nua von Indianakropfn eanäan - des luftige Biskwit mit da Vanillikreem is aafoch a Traum!'),
  ('idipfaereida', 'Idipfäreida', 'der', '', '', 'Echte Wiener Schmähperlen', 'I-Tüpfel-Reiter', '[{"kategorie": "wörtlich", "text": "\"I-Tüpfel-Reiter\" (Determinativkompositum aus \"I-Tüpfel\"=\"der Punkt über dem i\" und \"Reiter\"=\"jemand, der auf jedem noch so kleinen I-Punkt herumreitet\")"}, {"kategorie": "allg.", "text": "Pedant, Besserwisser, [[Pitzla]], [[Zwianscheissa]], [[Eabsnzööla]], [[Quarglschdecha]], [[Griaskeandlaunogla]] [\"Grießkörnchenannagler\"]"}]'::jsonb, 'Mei Schääf is soo a Idipfäreida - dea dädad sogoa in da Biibl nooch Tippfööla suachn!'),
  ('idipfalreida', 'Idipfalreida', 'der', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'I-Tüpfelchen-Reiter', '[{"kategorie": "wörtlich", "text": "\"I-Tüpfelchen-Reiter\" (Determinativkompositum aus \"I-Tüpfelchen\"=\"das Pünktchen über dem i\" und \"Reiter\"=\"jemand, der auf jedem noch so kleinen I-Punkt herumreitet\")"}, {"kategorie": "allg.", "text": "Pedant, Besserwisser, [[Pitzla]], [[Zwianscheissa]], [[Eabsnzööla]], [[Quarglschdecha]], [[Griaskeandlaunogla]] [\"Grießkörnchenannagler\"]"}]'::jsonb, 'So a Idipfälreida - dea wiad neavöös, waunna Beischdrich woogld!'),
  ('eabsnzoeoela', 'Eabsnzööla', 'der', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Erbsenzähler', '[{"kategorie": "wörtlich", "text": "\"Erbsenzähler\" (Determinativkompositum aus \"Erbse\"=\"Hülsenfrucht\" und \"Zähler\"=\"jemand, der jede einzelne Erbse zählt\")"}, {"kategorie": "allg.", "text": "Pedant, Besserwisser, [[Pitzla]], [[Zwianscheissa]], [[Idipfäreida]], [[Quarglschdecha]], [[Griaskeandlaunogla]] [\"Grießkörnchenannagler\"]"}]'::jsonb, 'Mit dem kaunnst ned auf Ualaub foan - dea Eabsnzööla reegd si scho auf, waunnst auf da Pizza a Olivn mea host ois ea!'),
  ('lausklauwa', 'Lausklauwa', 'der', '', '', 'Echte Wiener Schmähperlen', 'Lausklauber', '[{"kategorie": "wörtlich", "text": "\"Läusepicker\" (Determinativkompositum aus \"Läuse\"=\"Kopfläuse\" und \"Klauber\"=\"Picker\")"}, {"kategorie": "allg.", "text": "\"Läuse-Herauspicker\", Pedant, Besserwisser, [[Pitzla]], [[Zwianscheissa]], [[Idipfäreida]], [[Quarglschdecha]], [[Griaskeandlaunogla]] [\"Grießkörnchenannagler\"]"}]'::jsonb, 'Maunche haum in Sinn fias Groosse - aundare bleim a Leebm laung deppade Lausklauwa!'),
  ('liising', 'Liising', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Liesing', '[{"kategorie": "wörtlich", "text": "\"Wien-Liesing\""}, {"kategorie": "", "text": "\"der dreiundzwanzigste [[Hieb]]\" (= 23. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Liesing liegt im Südwesten Wiens und grenzt innerstädtisch an die Bezirke [[Favoriten]] (10.) im Osten, [[Meidling]] (12.) und [[Hietzing]] (13.) im Norden, sowie an die niederösterreichischen Gemeinden Perchtoldsdorf, Brunn am Gebirge, Maria Enzersdorf und Vösendorf"}, {"kategorie": "", "text": "Geprägt ist der Bezirk durch den [[Liesingbach]] (namensgebend), Hügel und Ausläufer des [[Wienerwaldes]], und eine Mischung aus urbanen Siedlungen, Gewerbegebieten und ländlichem Charakter"}, {"kategorie": "", "text": "Liesing besteht aus alten Ortskernen, die im Laufe des 20. Jahrhunderts nach Wien eingemeindet wurden, darunter [[Atzgersdorf]], [[Inzersdorf]], [[Mauer]] (mit Weingärten und Heurigen), Liesing (Zentrum, Bahnhof, Verwaltung), \n[[Rodaun]] (Wienerwaldnähe, Endstation der Straßenbahnlinie 60), [[Erlaa]] (bekannt durch [[Wohnpark]] Alt-Erlaa) und [[Siebenhirten]] (mit U6-Endstation)"}, {"kategorie": "", "text": "Liesing hat ca. 125.000 Einwohner und ist mit ca. 32,0 km² der flächenmäßig viertgrößte Bezirk Wiens"}, {"kategorie": "", "text": "Liesing entstand 1938 im Rahmen der Eingemeindungen durch das NS-Regime und bleib 1954 – im Gegensatz zu vielen anderen Gebieten – bei Wien. Seither hat sich Liesing vom Dorfbezirk zum Vorstadtwohngebiet mit stetig wachsender Bevölkerung entwickelt"}, {"kategorie": "", "text": "Liesing bietet viel Naturraum für Spaziergänge, Sport und Naherholung, wie z.B. den [[Liesingbach]] (beliebter Spazier- und Radweg), den [[Maurer]] Wald und andere [[Wienerwald-Ausläufer]], das Erholungsgebiet [[Perchtoldsdorfer]] Heide (an der Stadtgrenze), den [[Draschepark]], den Pappelteich, Weinberge in Mauer (mit Heurigenkultur) und das [[Schloss]] Rodaun (Kultur & Bildung)"}, {"kategorie": "", "text": "Liesing (der südlichste Stadtbezirk Wiens) ist heute geprägt von einer harmonischen Verbindung aus urbanem Wohnen, Industrie, alten Dörfern, Natur und Weinbau. Es ist ein Bezirk der Gegensätze, der durch Vielfalt, Ruhe und wachsende Infrastruktur besonders für Familien und Naturfreunde attraktiv ist."}]'::jsonb, ''),
  ('iwamiadich', 'iwamiadich', '', '', '', 'Grundwortschatz Wienerisch', 'übermütig', '[{"kategorie": "wörtlich", "text": "\"übermütig\" (vom mittelhochdeutschen \"übermuotelich\"=\"übermütig\")"}, {"kategorie": "pejorativ", "text": "hochmütig, stolz, überheblich, sich zu viel zutrauend"}, {"kategorie": "positiv konnotiert", "text": "ausgelassen, überschwänglich, ungezügelt, voller Elan, außer Rand und Band"}]'::jsonb, 'So iwamiadich, wia dea si giibd, kunntad ma maanan, dea hod de Wööd allaanich eafundn!'),
  ('jaukal', 'Jaukal', 'das', '', '', 'Krank & kuriert auf Wienerisch', 'Jaukerl', '[{"kategorie": "wörtlich", "text": "\"Piekserchen\" (vom mittelhochdeutschen \"jouchen\"=\"hineintreiben\")"}, {"kategorie": "med.", "text": "Nadelstich, \"Schuss\", \"Piekser\", \"Spritze\" (das Hineintreiben [\"Hineinjauken\"] einer Flüssigkeit in den Körper mittels Spritze und Nadel)"}, {"kategorie": "med.", "text": "Impfung, Schutzimpfung, Impfstoffgabe"}]'::jsonb, 'Des is nua a klaans Jaukal, des meaksd ned amoi!'),
  ('jausn', 'Jausn', 'die', '', '', 'Grundwortschatz Wienerisch', 'Jausen', '[{"kategorie": "wörtlich", "text": "\"Jause\" (vom mittelhochdeutschen \"jūs\"=\"Zwischenmahlzeit\")"}, {"kategorie": "allg.", "text": "Brotzeit, \"Snack\", kalte Zwischenmahlzeit am Vormittag"}]'::jsonb, 'Bei ana Waundarung hob I imma a Jausn im Rucksock!'),
