  ('teejausn', 'Teejausn', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Teejausen', '[{"kategorie": "wörtlich", "text": "\"Teejause\" (Determinativkompositum aus \"Tee\"=\"Aufgussgetränk\" und \"Jause\"=\"Zwischenmahlzeit\")"}, {"kategorie": "allg.", "text": "Teepause am Nachmittag, Tasse Tee und Kuchen, \"Nachmittagstee\", \"Teezeit\", \"Teekränzchen\""}]'::jsonb, 'Zua Teejausn gibds imma an frischn Obstfleck!'),
  ('kaffeejausn', 'Kaffeejausn', 'die', '', '', 'Wiener Kaffeehaus-ABC', 'Kaffeejausen', '[{"kategorie": "wörtlich", "text": "\"Kaffeejause\" (Determinativkompositum aus \"Kaffee\"=\"Aufgussgetränk\" und \"Jause\"=\"Zwischenmahlzeit\")"}, {"kategorie": "allg.", "text": "Kaffeepause am Nachmittag, Tasse Kaffee und Kuchen, \"Nachmittagskaffee\", \"Kaffeezeit\", \"Kaffeekränzchen\""}]'::jsonb, 'Zua Kaffeejausn gibds imma Briooschkipfaln!'),
  ('jausngegna', 'Jausngegna', 'der', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Jausengegner', '[{"kategorie": "wörtlich", "text": "\"leicht zu besiegender Gegner\" (=Gegner, den man gleichsam \"zur [[Jause]] verspeist\", Determinativkompositum aus \"Jause\"=\"Zwischenmahlzeit\" und \"Gegner\"=\"Konkurrent\")"}, {"kategorie": "Sport", "text": "[[Eiergegner]], \"Aufwärmgegner\", \"ganz schwacher Gegner\", \"Punktelieferant\", \"Aufbaugegner\", \"leichte Beute\""}]'::jsonb, 'Rapid hod si gestan wiara Jausngegna präsentiad!'),
  ('eiagegna', 'Eiagegna', 'der', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Eiergegner', '[{"kategorie": "wörtlich", "text": "\"leicht zu besiegender Gegner\" (Determinativkompositum aus \"Eier\"=\"Dilettanten\" und \"Gegner\"=\"Konkurrent\")"}, {"kategorie": "Sport", "text": "[[Jausengegner]], \"ganz schwacher Gegner\", \"Aufwärmgegner\", \"Punktelieferant\", \"leichte Beute\""}]'::jsonb, 'So an Eiagegna hauma scho laung nimma zuaglost kriagd!'),
  ('jassisch', 'jassisch', '', '', '', 'Grundwortschatz Wienerisch', 'jassisch', '[{"kategorie": "wörtlich", "text": "\"meisterhaft\" (von [[Jass]]= \"Meister\" bzw. \"Könner\")"}, {"kategorie": "allg.", "text": "genial, \"meisterhaft durchdacht\", exzellent, brillant, bravourös"}]'::jsonb, 'Wos fiara jassischa Schachzug - des woa Taktik auf heechstn Nivoo!'),
