  ('tarock', 'Tarock', 'das', '', '', 'Wiener Kartentipplerjargon', 'Tarock', '[{"kategorie": "wörtlich", "text": "\"Tarock\" (vom italienischen \"tarocco\"=\"Tarock\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"Tarockspiel\" (\"beliebtes Wiener Stichkartenspiel für zwei, drei oder vier Personen\", siehe [[Zwanzigerrufen]] und [[Königrufen]])"}, {"kategorie": "", "text": "\"Tarock, die\"): Tarockkarte (Stichkarte mit römischen Ziffern von \"I\" [[[Pagat]]] bis \"XXI\" [[[Mond]]], sowie dem [[Sküs]] [\"Gschdiiss\"])"}]'::jsonb, 'walaad gee'),
  ('tarockian', 'tarockian', '', '', '', 'Wiener Kartentipplerjargon', 'tarockieren', '[{"kategorie": "wörtlich", "text": "\"Tarock spielen\" (vom italienischen \"tarocco\" = \"Tarock\")"}, {"kategorie": "allg.", "text": "\"eine [[Tarockpartie]] spielen\", \"eine Runde Tarock klopfen\", \"eine Runde Tarock ausspielen\""}]'::jsonb, 'Wea tarockiad, brauchd Geduid, Schmää und a guade Haund!'),
  ('tarockiira', 'Tarockiira', 'der', '', '', 'Wiener Kartentipplerjargon', 'Tarockierer', '[{"kategorie": "wörtlich", "text": "\"jemand, der [[Tarock]] spielt\" (vom italienischen \"tarocco\"=\"Tarock\")"}, {"kategorie": "Kartenspielerjargon", "text": "Tarockspieler, [[Tarockant]]"}]'::jsonb, 'A echta Tarockiira waass - zeaschd wiad gschdochn, dann easchd gschbrochn!'),
