  ('tarockand', 'Tarockand', 'der', '', '', 'Wiener Kartentipplerjargon', 'Tarockant', '[{"kategorie": "wörtlich", "text": "\"jemand, der [[Tarock]] spielt\" (vom italienischen \"tarocco\"=\"Tarock\")"}, {"kategorie": "Kartenspielerjargon", "text": "Tarockspieler, [[Tarockierer]]"}]'::jsonb, ''),
  ('tarockaniaen', 'Tarockaniän', 'das', '', '', 'Wiener Kartentipplerjargon', 'Tarockanien', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Tarockanien\" (\"Fantasieland, dessen Verfassung auf den Regeln des Tarockspiels beruht\" - das Kunstwort „Tarockanien“ ist eine wunderbare, ironisch-literarische Wortschöpfung, die sich an „Kakanien“ [aus Robert Musils „Der Mann ohne Eigenschaften“] anlehnt – also an das alte, leicht absurde, überbürokratisierte und zugleich romantisierte Österreich-Ungarn)"}, {"kategorie": "scherzhaft für", "text": "\"das Reich der Tarocke\", [[Tarockistan]], [[Tarockei]]"}]'::jsonb, 'In Tarockaniän wiad ned gwööd - doo wiad gschdochn!'),
  ('tarockpartii', 'Tarockpartii', 'die', '', '', 'Wiener Kartentipplerjargon', 'Tarockpartie', '[{"kategorie": "wörtlich", "text": "\"Tarockpartie\" (Determinativkompositum aus [[Tarock]]=\"beliebtes Wiener Kartenspiel\" und [[Partie]]=\"Spielrunde\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"Tarockrunde\", \"Kartenrunde\", \"eine Spielrunde Tarock\", [[Tarockiererei]]"}, {"kategorie": "Kartenspielerjargon", "text": "\"Tarock-Team\", \"Tarock-Truppe\", \"Tarockstammtisch\" (gesellige Zusammenkunft zum Tarockieren), \"Gstieß-Gipfeltreffen\""}]'::jsonb, 'Dea froogd: ''No a Tarockpartii?'' - dabei woas schoo viire in da Frua!'),
  ('tarockiirarei', 'Tarockiirarei', 'die', '', '', 'Wiener Kartentipplerjargon', 'Tarockiererei', '[{"kategorie": "wörtlich", "text": "\"Tarockiererei\" (vom italienischen \"tarocco\"=[[Tarock]] [beliebtes Wiener Kartenspiel])"}, {"kategorie": "Kartenspielerjargon", "text": "\"das Tarockspielen\", \"Tarockrunde\", \"Kartenrunde\", [[Tarockpartie]], [[Kartlerei]]"}, {"kategorie": "Kartenspielerjargon", "text": "\"Tarockspielabend\", \"Tarockstammtisch\" (gesellige Zusammenkunft zum Tarockieren), \"Gstieß-Gipfeltreffen\", \"Kartengeplänkel\""}]'::jsonb, 'De Tarockiirarei is wiara Suchd - waunnsd amoi damit aufaungsd, kaunnsd nimma aufhean!'),
  ('kartlarei', 'Kartlarei', 'die', '', '', 'Wiener Kartentipplerjargon', 'Kartlerei', '[{"kategorie": "wörtlich", "text": "\"Kartlerei\" (vom mittelhochdeutschen \"karten\"=\"mit Karten spielen\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"das Kartenspielen\", \"Kartenrunde\", \"Kartenpartie\""}, {"kategorie": "Kartenspielerjargon", "text": "\"Kartenspielabend\", \"Kartenstammtisch\" (gesellige Zusammenkunft zum Tarockieren), \"Kartenspieler-Gipfeltreffen\""}]'::jsonb, 'De Kartlarei is wiara Suchd - waunnsd amoi damit aufaungsd, kaunnsd nimma aufhean!'),
