  ('tarockei', 'Tarockei', 'die', '', '', 'Wiener Kartentipplerjargon', 'Tarockei', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Tarockei\" (\"Fantasieland, dessen Verfassung auf den Regeln des Tarockspiels beruht\"  - das Kunstwort „Tarockei“ ist eine ironische Wortschöpfung, die sich an das Wort \"Tschechei\" [Tschechien] anlehnt – also an das alte, leicht absurde, überbürokratisierte und zugleich romantisierte Österreich-Ungarn)"}, {"kategorie": "scherzhaft für", "text": "\"das Reich der Tarocke\", [[Tarockistan]], [[Tarockanien]]"}]'::jsonb, 'In da Tarockei wiad ned gwööd - doo wiad gschdochn!'),
  ('tarockistan', 'Tarockistan', 'das', '', '', 'Wiener Kartentipplerjargon', 'Tarockistan', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Tarockistan\" (\"Fantasieland, dessen Verfassung auf den Regeln des Tarockspiels beruht\"  - das Kunstwort „Tarockistan“ ist eine ironische Wortschöpfung, die sich an das Wort \"Pakistan\" anlehnt – also an das alte, leicht absurde, überbürokratisierte und zugleich romantisierte Morgenland)"}, {"kategorie": "scherzhaft für", "text": "\"das Reich der Tarocke\", [[Tarockanien]], [[Tarockei]]"}]'::jsonb, 'In Tarockistan wiad ned gwööd - doo wiad gschdochn!'),
  ('schnopsa', 'Schnopsa', 'der', '', '', 'Wiener Kartentipplerjargon', 'Schnapser', '[{"kategorie": "wörtlich", "text": "\"Schnapser\" (vom mittelhochdeutschen \"snappen\"=\"etwas schnell greifen oder schlucken\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"eine Kartenpartie [[Schnapsen]]\", \"eine Runde [[Schnapsen]]\" (=Kartenspiel \"66\"), \"eine Schnapspartie\""}, {"kategorie": "Kartenspielerjargon", "text": "\"Spiel beim [[Bauernschnapsen]] (der Ansager muss alle fünf Stiche machen, das Atout wird außer Kraft gesetzt), \"Spielansage, wonach man alle Stiche machen wird\""}, {"kategorie": "Kartenspielerjargon", "text": "\"leidenschaftlicher Schnapsspieler\", \"Schnapsfreund\", \"Schnapsliebhaber\""}]'::jsonb, 'Ois oida Schnopsa waassa genau, wööche Koatn schoo draussn san!'),
